<script setup lang="ts">
const email=ref('');const password=ref('');const code=ref('');const error=ref('');const busy=ref(false);const base=useRuntimeConfig().app.baseURL
async function login(){error.value='';busy.value=true;try{await $fetch(`${base}api/login`,{method:'POST',body:{email:email.value,password:password.value,code:code.value}});window.location.assign(`${base}auth/rednote`)}catch{error.value='登录失败，请检查账号、密码和验证码。'}finally{busy.value=false}}
</script>
<template><div class="login-wrap"><UCard class="login-card"><h1 class="title">RedNote 管理后台</h1><p class="subtitle">使用管理员账号及身份验证器登录</p><form class="form" @submit.prevent="login"><div><label for="email">邮箱</label><UInput id="email" v-model="email" type="email" autocomplete="username" required class="w-full"/></div><div><label for="password">密码</label><UInput id="password" v-model="password" type="password" autocomplete="current-password" required class="w-full"/></div><div><label for="code">身份验证器验证码</label><UInput id="code" v-model="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" required class="w-full"/></div><p v-if="error" role="alert" class="error">{{error}}</p><UButton type="submit" label="安全登录" :loading="busy" block/></form></UCard></div></template>
